mapper.sql:
SELECT product.*
FROM sc_buyer_product product
JOIN sc_platform_sku sku ON sku.id = product.platform_sku_id
JOIN sc_platform_spu spu ON spu.id = sku.spu_id
WHERE product.buyer_id = #{buyerId}
  AND product.status = #{activeStatus}

  AND spu.product_type IN

      #{productType}



  AND (spu.spu_name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!'
       OR spu.spu_code LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!'
       OR sku.sku_name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!'
       OR sku.sku_code LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!')


  AND spu.primary_category_id IN

      #{categoryId}



  AND NOT EXISTS (
      SELECT 1 FROM sc_project_listing listing
      WHERE listing.project_id = #{projectId}
        AND listing.buyer_product_id = product.id
        AND listing.status = #{availableStatus}
  )

ORDER BY product.updated_at DESC
